// ============================================================================

const workflows = $input.first().json.data || [];

// Filter active MCP workflows (excluding this registry)
const mcpWorkflows = workflows.filter(w => 
  w.active && 
  w.name.startsWith('MCP -') && 
  w.name !== 'MCP - Registry'
);

// Build tools object
const tools = {};

for (const workflow of mcpWorkflows) {
  const webhookNode = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.webhook');

  if (webhookNode) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;
    const toolName = webhookPath;

    // Get metadata (label, tags, scope, description)
    const meta = toolMetadata[toolName] || {};

    // Get schema (parameters)
    const schema = toolSchemas[toolName] || null;

    tools[toolName] = {
      name: workflow.name,
      label: meta.label || workflow.name.replace('MCP - ', ''),
      icon: meta.icon || ({'email':'📧','calendar':'📅','contacts':'👥','storage':'💾','document':'📄','search':'🔍','ai-text':'✨','ai-image':'🎨','ai-audio':'🎙️','ai-code':'💻','analytics':'📊','social':'🌐','education':'🎓','utility':'🔧','ocr':'👁️','translation':'🌍'}[(meta.tags||[])[0]] || '🔧'),
      description: meta.description || `MCP Tool: ${workflow.name}`,
      tags: meta.tags || [],
      scope: meta.scope || "user",
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `http://pi6.local:5678/webhook/${webhookPath}`,
      method: "POST",
      active: workflow.active,
      parameters: schema?.parameters || { required: {}, optional: {} }
    };
  }
}

